#!/usr/bin/env python3
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-03
"""A0.3 — attach per-thread scheduling attributes (snapshot/threads_<tag>.json, written by
fish.snapshot.capture_thread_attrs) to the executor vertices of a session.

Usage: python3 attach_thread_attrs.py <session_id> [--tag stable|shutdown] [--scope __main__]

For every EX vertex (one per traced process, pid = container vpid) sets attrs:
  threads: [{tid, comm, policy, prio, nice, cpus_allowed_list}]      (all threads of the process)
  thread_summary: {n_threads, policies: {OTHER: n, FIFO: n, ...}, rt_threads: n, cpus_allowed_list: [...distinct]}
A task model needs these for the scheduler side: which threads are real-time, their priorities
and which cores they may run on.  policy codes: 0 OTHER, 1 FIFO, 2 RR, 3 BATCH, 5 IDLE, 6 DEADLINE."""
import argparse, collections, json, os, sys
import psycopg2
DSN = 'host=localhost port=5432 dbname=fish user=fish password=fish'
POL = {0: 'OTHER', 1: 'FIFO', 2: 'RR', 3: 'BATCH', 5: 'IDLE', 6: 'DEADLINE'}

def main():
    ap = argparse.ArgumentParser(); ap.add_argument('session'); ap.add_argument('--tag', default='stable')
    ap.add_argument('--scope', default='__main__'); ap.add_argument('--traces', default=os.path.expanduser('~/fish_traces'))
    a = ap.parse_args()
    path = os.path.join(a.traces, a.session, 'snapshot', f'threads_{a.tag}.json')
    if not os.path.exists(path):
        sys.exit(f'no {path} (image/session without capture_thread_attrs)')
    snap = json.load(open(path))
    conn = psycopg2.connect(DSN); c = conn.cursor()
    c.execute("SELECT node_id, pid FROM graph_nodes WHERE session_id=%s AND scope=%s AND type='EX'", (a.session, a.scope))
    n_set = 0; rt_total = 0
    for node_id, pid in c.fetchall():
        info = snap.get(str(pid))
        if not info: continue
        thr = info['threads']
        pols = collections.Counter(POL.get(t['policy'], str(t['policy'])) for t in thr)
        rt = sum(1 for t in thr if t['policy'] in (1, 2, 6)); rt_total += rt
        summary = {'n_threads': len(thr), 'policies': dict(pols), 'rt_threads': rt,
                   'cpus_allowed_list': sorted({t['cpus_allowed_list'] for t in thr})}
        c.execute("UPDATE graph_nodes SET attrs = attrs || %s::jsonb WHERE session_id=%s AND scope=%s AND node_id=%s",
                  (json.dumps({'threads': [{k: t[k] for k in ('tid', 'comm', 'policy', 'prio', 'nice', 'cpus_allowed_list')} for t in thr],
                               'thread_summary': summary, 'threads_tag': a.tag}), a.session, a.scope, node_id))
        n_set += 1
    conn.commit()
    print(f'attach_thread_attrs: {n_set} executor(s) got thread attributes from {path}; {rt_total} real-time threads in total')
    # quick overview
    allc = collections.Counter(); affin = collections.Counter()
    for p, info in snap.items():
        for t in info['threads']:
            allc[POL.get(t['policy'], str(t['policy']))] += 1; affin[t['cpus_allowed_list']] += 1
    print('policies (all threads in the container):', dict(allc)); print('affinity sets:', dict(affin.most_common(4)))

if __name__ == '__main__':
    main()
